import { git } from '../git.ts';
import { loadProject } from '../project.ts';
import type { Project, Ready, Review } from '../model.ts';
import { matchesReviewContent } from '../review-records.ts';
export interface Comparison {
  base: string; label: string; before: Record<string, string>;
  summariesBefore: Record<string, string[]>;
  removed: { title: string; body: string }[];
}
const bases = new Map<string, Project>();
export function comparison(root: string, project: Project, pending: Ready | null, history: { path: string; review: Review }[], tree: string): Comparison | null {
  let base: string | undefined, label = 'Proposed changes';
  const changed = git(root, ['diff', '--name-only', 'HEAD', tree, '--', 'stratic/descriptions']).trim();
  if (project.revision === 'working' && pending) base = pending.base;
  else if (project.revision === 'working' && changed) base = git(root, ['rev-parse', 'HEAD']).trim();
  else {
    for (const { path, review } of [...history].sort((a, b) => String(b.review.recordedAt).localeCompare(String(a.review.recordedAt)))) {
      if (matchesReviewContent(root, tree, path, review)) { base = review.base; label = 'Accepted changes'; break; }
    }
  }
  if (!base) return null;
  const key = JSON.stringify([root, base]);
  let previous = bases.get(key);
  if (!previous) { previous = loadProject(root, base); if (bases.size >= 4) bases.delete(bases.keys().next().value!); bases.set(key, previous); }
  const before: Record<string, string> = Object.create(null);
  const summariesBefore: Record<string, string[]> = Object.create(null);
  for (const d of project.descriptions) {
    const old = previous.descriptions.find(old => old.id === d.id)?.body ?? '';
    if (old !== d.body) before[d.id] = old;
    const oldSummary = previous.descriptions.find(old => old.id === d.id)?.metadata?.summary ?? [];
    if (JSON.stringify(oldSummary) !== JSON.stringify(d.metadata?.summary ?? [])) summariesBefore[d.id] = oldSummary;
  }
  return { base, label, before, summariesBefore, removed: previous.descriptions.filter(d => !project.descriptions.some(next => next.id === d.id)).map(d => ({ title: d.title, body: d.body })) };
}

// Compare paragraphs so highlighting follows the description, not its selected passage.
export function textChanges(before: string, after: string) {
  const chunks = (s: string) => [...s.matchAll(/[^\n]+(?:\n(?!\n)[^\n]+)*/g)].map(m => ({ text: m[0], start: m.index!, end: m.index! + m[0].length }));
  const a = chunks(before), b = chunks(after);
  const additions: { start: number; end: number }[] = [], removed: string[] = [];
  // Bound memory for unusually fragmented files; a whole-text change is still accurate.
  if (a.length * b.length > 1_000_000) return { additions: before === after ? [] : [{ start: 0, end: after.length }], removed: before === after || !before ? [] : [before] };
  const width = b.length + 1, lengths = new Uint32Array((a.length + 1) * width);
  for (let i = a.length - 1; i >= 0; i--) for (let j = b.length - 1; j >= 0; j--) {
    lengths[i * width + j] = a[i].text === b[j].text ? 1 + lengths[(i + 1) * width + j + 1] : Math.max(lengths[(i + 1) * width + j], lengths[i * width + j + 1]);
  }
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i].text === b[j].text) { i++; j++; }
    else if (j < b.length && (i === a.length || lengths[i * width + j + 1] >= lengths[(i + 1) * width + j])) { additions.push({ start: b[j].start, end: b[j].end }); j++; }
    else { removed.push(a[i].text); i++; }
  }
  return { additions, removed };
}

